From 2644f123d0e2560641180aba9437ad5043d71c96 Mon Sep 17 00:00:00 2001
From: Matthias Klumpp <matthias@tenstral.net>
Date: Sat, 21 Mar 2015 18:25:11 +0100
Subject: [PATCH] Fix another archive layout issue

This one was introduced with the previous "fix" in c338b04.
Good that we have tests.

diff --git a/src/li-pkg-builder.c b/src/li-pkg-builder.c
index 91e45bb..c0fa5dc 100644
--- a/src/li-pkg-builder.c
+++ b/src/li-pkg-builder.c
@@ -97,18 +97,21 @@ li_get_package_fname (const gchar *root_dir, const gchar *disk_fname)
 {
 	gchar *tmp;
 	gchar *fname = NULL;
+	_cleanup_free_ gchar *root_prefix = NULL;
 	gint offset;

 	if (g_str_has_prefix (disk_fname, root_dir)) {
 		fname = g_strdup (disk_fname + strlen (root_dir) + 1);
 	}

+	root_prefix = g_strdup (LI_SW_ROOT_PREFIX + 1);
+
 	if (fname != NULL) {
-		if (g_str_has_prefix (fname, LI_SW_ROOT_PREFIX)) {
+		if (g_str_has_prefix (fname, root_prefix)) {
 			tmp = g_strdup (fname);
 			g_free (fname);

-			offset = strlen (LI_SW_ROOT_PREFIX) + 1;
+			offset = strlen (root_prefix) + 1;
 			if (strlen (tmp) > offset)
 				fname = g_strdup (tmp + offset);
 			else
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the use of a hardcoded prefix (`LI_SW_ROOT_PREFIX`) in the filename processing logic, which did not account for variations in the root directory structure. This led to incorrect handling of package filenames when they were expected to have a different prefix, resulting in an archive layout issue.

        Commit message:
        Fix another archive layout issue

This one was introduced with the previous "fix" in c338b04.
Good that we have tests.  

        Patch:
          */
 static gchar*
 li_get_package_fname (const gchar *root_dir, const gchar *disk_fname)
 {
 	gchar *tmp;
 	gchar *fname = NULL;
+	_cleanup_free_ gchar *root_prefix = NULL;
 	gint offset;

 	if (g_str_has_prefix (disk_fname, root_dir)) {
 		fname = g_strdup (disk_fname + strlen (root_dir) + 1);
 	}

+	root_prefix = g_strdup (LI_SW_ROOT_PREFIX + 1);
+
 	if (fname != NULL) {
-		if (g_str_has_prefix (fname, LI_SW_ROOT_PREFIX)) {
+		if (g_str_has_prefix (fname, root_prefix)) {
 			tmp = g_strdup (fname);
 			g_free (fname);

-			offset = strlen (LI_SW_ROOT_PREFIX) + 1;
+			offset = strlen (root_prefix) + 1;
 			if (strlen (tmp) > offset)
 				fname = g_strdup (tmp + offset);
 			else
 				fname = NULL;
 			g_free (tmp);
 		}
 	}

 	if (fname == NULL)
 		return g_strdup (disk_fname);
 	else
 		return fname;
 }



